INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q143','nism-5b-z0','A goal costs ₹83,000 today. With inflation of 6% p.a., its cost after 15 years will be approximately:','["₹1,87,655","₹2,10,849","₹1,98,914","₹1,57,700"]',2,'FV = 83000 × (1 + 6%)^15.',143) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q144','nism-5b-z0','A scheme with average net assets of ₹5700 crore incurs total recurring expenses of ₹3.80 crore in a year. Its expense ratio is:','["0.100%","0.033%","0.067%","0.133%"]',2,'TER = 3.80 ÷ 5700 × 100 = 0.067%.',144) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
