INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q725','nism-5b-z0','A fund returned 11% with a standard deviation of 12%. The risk-free rate is 6%. The Sharpe ratio is:','["0.36","0.42","0.92","1.42"]',1,'Sharpe = (11 − 6) ÷ 12.',725) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q726','nism-5b-z0','A fund returned 21% with a standard deviation of 13%. The risk-free rate is 7%. The Sharpe ratio is:','["2.15","0.93","1.62","1.08"]',3,'Sharpe = (21 − 7) ÷ 13.',726) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q727','nism-5b-z0','A fund returned 11% with a standard deviation of 6%. The risk-free rate is 7%. The Sharpe ratio is:','["1.83","0.67","0.50","3.00"]',1,'Sharpe = (11 − 7) ÷ 6.',727) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q728','nism-5b-z0','An investor invests ₹80,000 in an open-ended scheme at an NAV of ₹78.10. With no entry load, the number of units allotted is:','["8000.000","1001.788","6248000.000","1024.328"]',3,'Units = 80000 ÷ 78.10 = 1024.328.',728) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z0-q729','nism-5b-z0','An investor holds 165 units under the IDCW Reinvestment option. IDCW is ₹1.5 per unit and the ex-IDCW NAV is ₹20. The additional units allotted are:','["24.75","11.51","12.38","247.50"]',2,'Units = (165 × 1.5) ÷ 20 = 12.38.',729) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
